export const BODY: string = "\n<p>PNG کو JPG میں بدلنا سب سے عام تبدیلی ہے، کیونکہ PNG اسکرین شاٹ بہت بڑے ہوتے ہیں اور JPG انہیں دس گنا چھوٹا کر دیتا ہے۔ یہ تبدیلی ای میل، ویب سائٹ اور فارم کے لیے ضروری ہے۔</p>\n<p>لیکن تبدیلی میں دو باتیں جاننی ضروری ہیں: شفافیت ختم ہو جاتی ہے، اور متن دھندلا ہو سکتا ہے۔ ان دونوں کو سمجھ کر تبدیلی کریں تو نتیجہ بہترین ہوتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ PNG اسکرین شاٹ بڑے کیوں ہوتے ہیں، کون سی سیٹنگ کام کرتی ہے، میٹ رنگ کیا ہے، اور عام غلطیوں سے کیسے بچیں۔ تبدیل کرنے کے لیے <a href=\"/ur/png-ko-jpg-mein-convert-karein/\">PNG ٹو JPG</a> استعمال کریں۔</p>\n<h2 id=\"what-is-png-to-jpg\">PNG ٹو JPG تبدیلی کیا ہے؟</h2>\n<p>PNG کے پکسلز کو JPG فارمیٹ میں دوبارہ لکھا جاتا ہے، جس سے فائل بہت چھوٹی ہو جاتی ہے۔ تصویر ویسی ہی نظر آتی ہے، مگر اس کا وزن کم ہو جاتا ہے۔</p>\n<p>تبدیلی میں شفافیت ختم ہو جاتی ہے، کیونکہ JPG شفافیت نہیں جانتا۔ شفاف حصہ میٹ رنگ سے بھر جاتا ہے، جو اکثر سفید ہوتا ہے۔</p>\n<p>یہ تبدیلی اس وقت کریں جب فائل سائز اہم ہو اور شفافیت کی ضرورت نہ ہو۔ فوٹو اور اسکرین شاٹ کے لیے یہ بہترین ہے۔</p>\n<h2 id=\"why-screenshots-are-huge\">PNG اسکرین شاٹ اتنے بڑے کیوں ہوتے ہیں؟</h2>\n<p>اسکرین شاٹ میں ہزاروں رنگ اور تیز کنارے ہوتے ہیں، جنہیں PNG بغیر نقصان کے محفوظ کرتا ہے۔ اس لیے ایک اسکرین شاٹ کئی میگا بائٹ کا ہو سکتا ہے۔</p>\n<p>فون کا اسکرین شاٹ بھی بڑا ہوتا ہے، کیونکہ فون کی اسکرین کا ریزولوشن بہت زیادہ ہے۔ 2000 پکسلز چوڑا اسکرین شاٹ PNG میں 3MB سے زیادہ ہو سکتا ہے۔</p>\n<p>اسکرین شاٹ کو JPG میں بدلنے سے وہ 300KB بن جاتا ہے، بغیر متن خراب کیے، اگر معیار 85 رکھا جائے۔</p>\n<h2 id=\"quality-settings\">معیار کی سیٹنگز جو کام کرتی ہیں</h2>\n<p>اسکرین شاٹ کے لیے 85 معیار بہترین ہے: متن تیز اور فائل چھوٹی۔ فوٹو کے لیے 80 کافی ہے، کیونکہ فوٹو میں متن نہیں ہوتا۔</p>\n<p>معیار 90 سے اوپر فائل بہت بڑی کر دیتا ہے، بغیر کوئی فائدہ دیے۔ معیار 70 سے نیچے متن دھندلا ہو جاتا ہے۔</p>\n<p>سیٹنگ چننے کے بعد نتیجہ کو مکمل سائز میں دیکھیں۔ اگر متن صاف پڑھا جائے تو سیٹنگ درست ہے۔</p>\n<h2 id=\"matte-colour\">میٹ رنگ: شفافیت کو بھرنا</h2>\n<p>میٹ رنگ وہ رنگ ہے جو شفاف حصے کو بھرتا ہے۔ سفید میٹ سب سے عام ہے، کیونکہ زیادہ تر پس منظر سفید ہوتا ہے۔</p>\n<p>اگر تصویر گہرے پس منظر پر لگنی ہو تو کالا میٹ چنیں، ورنہ سفید کنارہ نظر آئے گا۔ میٹ رنگ کو منزل کے پس منظر سے ملائیں۔</p>\n<p>میٹ رنگ غلط چننے سے لوگو کے گرد رنگین کنارہ نظر آتا ہے۔ لوگو کو JPG میں بدلنے سے پہلے میٹ رنگ جانچیں۔</p>\n<h2 id=\"screenshots-and-text\">اسکرین شاٹ اور متن کی وضاحت</h2>\n<p>اسکرین شاٹ میں متن سب سے اہم ہے، اور JPG متن کو سب سے زیادہ خراب کرتا ہے۔ اس لیے اسکرین شاٹ کا معیار 85 سے کم نہ رکھیں۔</p>\n<p>متن کو جانچنے کے لیے تصویر کو 100 فیصد زوم پر دیکھیں۔ اگر چھوٹا متن بھی صاف پڑھا جائے تو تبدیلی کامیاب ہے۔</p>\n<p>اگر متن دھندلا لگے تو معیار بڑھائیں یا PNG ہی رکھیں۔ دھندلا متن والی تصویر بیکار ہے، چاہے فائل کتنی چھوٹی ہو۔</p>\n<h2 id=\"product-photos-and-logos\">مصنوعات کی تصویریں، کٹ آؤٹ اور لوگو</h2>\n<p>مصنوعات کی تصویر JPG میں اچھی بنتی ہے، کیونکہ اس میں نرم رنگ ہوتے ہیں۔ لیکن کٹ آؤٹ اور لوگو میں شفافیت ہوتی ہے، جو JPG میں ختم ہو جاتی ہے۔</p>\n<p>لوگو کو JPG میں نہ بدلیں، اسے PNG میں ہی رکھیں۔ لوگو کا سفید پس منظر ہر جگہ عجیب لگتا ہے۔</p>\n<p>مصنوعات کی تصویر کو JPG میں بدلنے سے پہلے پس منظر دیکھیں: اگر پس منظر سفید ہے تو تبدیلی محفوظ ہے۔</p>\n<h2 id=\"batch-converting-screenshots\">اسکرین شاٹ کی بیچ تبدیلی</h2>\n<p>بیچ میں درجنوں اسکرین شاٹ ایک ساتھ JPG میں بدلے جا سکتے ہیں۔ یہ بہت وقت بچاتا ہے، خاص طور پر جب پوری دستاویز تیار کرنی ہو۔</p>\n<p>بیچ میں سب پر ایک ہی معیار لگائیں: اسکرین شاٹ کے لیے 85۔ بیچ کا نتیجہ ZIP میں ملتا ہے۔</p>\n<p>بیچ بدلنے سے پہلے ایک اسکرین شاٹ آزمائیں۔ اگر متن صاف ہو تو پوری بیچ بدلیں۔</p>\n<h2 id=\"file-size-savings\">فائل کا سائز کتنا بچ سکتا ہے؟</h2>\n<p>اسکرین شاٹ میں بچت پانچ سے دس گنا ہوتی ہے: 3MB PNG اسکرین شاٹ JPG میں 300KB بن جاتا ہے۔ فوٹو میں بچت اس سے بھی زیادہ ہوتی ہے۔</p>\n<p>بچت تصویر کی قسم پر منحصر ہے: سادہ اسکرین شاٹ میں زیادہ بچت، تفصیل والے میں کم۔ لیکن ہر تصویر میں کچھ بچت ضرور ہوتی ہے۔</p>\n<p>بچت جانچنے کے لیے ایک تصویر تبدیل کریں اور دونوں کا سائز دیکھیں۔ اگر بچت پانچ گنا سے زیادہ ہو تو تبدیلی ضرور کریں۔</p>\n<h2 id=\"png-vs-webp-decision\">PNG ٹو JPG یا PNG ٹو WebP؟</h2>\n<p>ویب کے لیے WebP بہتر ہے، کیونکہ وہ JPG سے بھی چھوٹا ہوتا ہے اور شفافیت بھی بچاتا ہے۔ شیئرنگ کے لیے JPG بہتر ہے، کیونکہ وہ ہر جگہ کھلتا ہے۔</p>\n<p>اگر شفافیت چاہیے تو WebP چنیں، کیونکہ JPG شفافیت مٹا دیتا ہے۔ اگر مطابقت چاہیے تو JPG چنیں۔</p>\n<p>دونوں میں سے کوئی بھی PNG سے بہتر ہے، کیونکہ دونوں فائل کو بہت چھوٹا کرتے ہیں۔</p>\n<h2 id=\"metadata-stripped\">تبدیلی کے دوران میٹا ڈیٹا ہٹ جاتا ہے</h2>\n<p>تبدیلی کے دوران میٹا ڈیٹا، جیسے مقام اور کیمرے کی معلومات، اکثر ہٹا دیا جاتا ہے۔ یہ پرائیویسی کے لیے اچھا ہے۔</p>\n<p>اگر میٹا ڈیٹا چاہیے تو اسے الگ محفوظ رکھیں، کیونکہ تبدیلی کے بعد وہ واپس نہیں ملتا۔</p>\n<p>میٹا ڈیٹا جانچنے کے لیے تبدیلی کے بعد تصویر کو ویور میں دیکھیں۔ اگر وہ صاف ہو تو تصویر شیئر کرنے کے لیے تیار ہے۔</p>\n<h2 id=\"checking-quality\">ڈاؤن لوڈ سے پہلے معیار جانچنا</h2>\n<p>ڈاؤن لوڈ سے پہلے تصویر کو مکمل سائز میں دیکھیں اور اصل سے موازنہ کریں۔ متن، آسمان اور جلد جانچیں۔</p>\n<p>اگر فرق نظر نہ آئے تو معیار درست ہے۔ اگر متن دھندلا ہو تو معیار بڑھائیں۔</p>\n<p>جانچ کے لیے پیش منظر پر بھروسہ نہ کریں۔ چھوٹے پیش منظر پر نقصان چھپ جاتا ہے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں جن سے بچیں</h2>\n<p>سب سے عام غلطی معیار کو بہت کم رکھنا ہے، جس سے متن دھندلا ہو جاتا ہے۔ دوسری غلطی شفاف لوگو کو JPG میں بدلنا ہے۔</p>\n<p>تیسری غلطی اصل PNG کو مٹا دینا ہے۔ اصل محفوظ رکھیں، تاکہ بعد میں دوبارہ تبدیل کر سکیں۔</p>\n<p>چوتھی غلطی میٹ رنگ غلط چننا ہے، جس سے لوگو کے گرد رنگین کنارہ نظر آتا ہے۔</p>\n<h2 id=\"png-photos-from-phones\">فون سے PNG تصویریں</h2>\n<p>فون کی PNG تصویریں اکثر اسکرین شاٹ ہوتی ہیں، جو بہت بڑی ہوتی ہیں۔ انہیں JPG میں بدلنے سے فون کی جگہ بہت بچتی ہے۔</p>\n<p>فون کی کیمرہ تصویریں JPG میں ہوتی ہیں، اس لیے انہیں بدلنے کی ضرورت نہیں۔ صرف اسکرین شاٹ کو بدلیں۔</p>\n<p>فون پر تبدیلی براؤزر میں ہوتی ہے، اس لیے کوئی ایپ انسٹال کرنے کی ضرورت نہیں۔</p>\n<h2 id=\"screenshots-bug-reports\">بگ رپورٹ کے لیے اسکرین شاٹ</h2>\n<p>بگ رپورٹ میں اسکرین شاٹ کا متن صاف ہونا چاہیے، تاکہ ڈویلپر مسئلہ سمجھ سکے۔ معیار 85 رکھیں، تاکہ متن پڑھا جا سکے۔</p>\n<p>بگ رپورٹ میں اسکرین شاٹ کو کراپ کریں، تاکہ صرف مسئلہ والا حصہ نظر آئے۔ پورا اسکرین شاٹ بھیجنے سے مسئلہ چھپ جاتا ہے۔</p>\n<p>بگ رپورٹ کی فائل چھوٹی رکھیں، تاکہ وہ جلدی اپ لوڈ ہو۔ JPG میں اسکرین شاٹ تیزی سے بھیجا جاتا ہے۔</p>\n<h2 id=\"sharing-screenshots-chats\">چیٹ میں اسکرین شاٹ شیئر کرنا</h2>\n<p>چیٹ میں PNG اسکرین شاٹ سست بھیجا جاتا ہے، کیونکہ وہ بہت بڑا ہوتا ہے۔ JPG میں بدلنے سے وہ تیزی سے بھیجا جاتا ہے۔</p>\n<p>چیٹ میں تصویر چھوٹی دکھائی دیتی ہے، اس لیے معیار 80 بھی کافی ہے۔ وصول کرنے والا تصویر کو بڑا کر کے دیکھ سکتا ہے۔</p>\n<p>چیٹ میں بھیجنے سے پہلے تصویر کا میٹا ڈیٹا صاف کریں، تاکہ آپ کا مقام نہ جائے۔</p>\n<h2 id=\"converting-for-email\">ای میل کے لیے تصویریں بدلنا</h2>\n<p>ای میل میں PNG تصویریں بہت بڑی ہوتی ہیں اور حد سے باہر ہو سکتی ہیں۔ JPG میں بدلنے سے وہ ای میل کی حد میں آ جاتی ہیں۔</p>\n<p>ای میل کے لیے معیار 80 رکھیں، تاکہ فائل ہلکی رہے۔ وصول کرنے والا تصویر کو جلدی ڈاؤن لوڈ کرتا ہے۔</p>\n<p>اگر ای میل میں بہت سی تصویریں ہوں تو انہیں ZIP میں ڈال کر بھیجیں۔</p>\n<h2 id=\"archiving-converted-jpgs\">تبدیل شدہ JPG محفوظ کرنا</h2>\n<p>تبدیل شدہ JPG کو الگ فولڈر میں محفوظ کریں اور اصل PNG بھی رکھیں۔ اصل سے بعد میں دوبارہ تبدیل کیا جا سکتا ہے۔</p>\n<p>آرکائیو میں تاریخ اور مقصد کے ساتھ نام رکھیں، تاکہ بعد میں تلاش کرنا آسان ہو۔ ایک نقل کلاؤڈ میں بھی رکھیں۔</p>\n<p>تبدیل شدہ JPG سے اصل PNG دوبارہ نہیں بنتا، اس لیے اصل کو کبھی نہ مٹائیں۔ فائل سائز اور معیار کی تفصیل <a href=\"/ur/blog/png-ko-jpg-file-size-aur-quality/\">PNG ٹو JPG فائل سائز اور معیار</a> میں اور عملی مراحل <a href=\"/ur/blog/png-ko-jpg-mein-kaise-convert-karein/\">PNG کو JPG میں کیسے بدلیں</a> میں دیکھیں۔ WebP چاہیے ہو تو <a href=\"/ur/png-ko-webp-mein-convert-karein/\">PNG ٹو WebP</a> استعمال کریں۔</p>\n";

